1	import OpenAI from 'openai';
2	import { wrapOpenAI } from 'neatlogs';
3	import { z } from 'zod';
4	import type { Env } from '@dailies/core';
5	import type { CostMeter } from './meter';
6	import { sharedLimiter } from './limiter';
7	import type { Tool } from './tools';
8	import { isTracingInitialized } from './trace';
9	
10	export type Role = 'editor' | 'extractor' | 'judge' | 'writer' | 'vision';
11	
12	export type ContentPart = { type: 'text'; text: string } | { type: 'image_url'; image_url: { url: string } };
13	
14	export interface ToolCall {
15	  id: string;
16	  type: 'function';
17	  function: { name: string; arguments: string };
18	}
19	
20	export interface ChatMessage {
21	  role: 'system' | 'user' | 'assistant' | 'tool';
22	  content: string | ContentPart[] | null;
23	  tool_calls?: ToolCall[];
24	  tool_call_id?: string;
25	}
26	
27	export interface Completion {
28	  message: ChatMessage;
29	  inputTokens: number;
30	  outputTokens: number;
31	  model: string;
32	  provider: string;
33	}
34	
35	export interface ModelClient {
36	  complete(req: { role: Role; messages: ChatMessage[]; tools?: Tool[]; maxTokens?: number }): Promise<Completion>;
37	}
38	
39	const MODEL_BY_ROLE: Record<Role, string> = {
40	  editor: 'claude-sonnet-4.6',
41	  writer: 'claude-sonnet-4.6',
42	  vision: 'claude-sonnet-4.6',
43	  extractor: 'claude-haiku',
44	  judge: 'nova-pro',
45	};
46	
47	const COST_PER_MILLION_TOKENS: Record<string, { input: number; output: number }> = {
48	  'claude-sonnet-4.6': { input: 3, output: 15 },
49	  'claude-haiku': { input: 1, output: 5 },
50	  'nova-pro': { input: 0.8, output: 3.2 },
51	};
52	
53	const RETRY_WAITS_MS = [1000, 2000, 4000];
54	
55	function sleep(ms: number): Promise<void> {
56	  return new Promise((resolve) => setTimeout(resolve, ms));
57	}
58	
59	function isRetryableStatus(status: unknown): boolean {
60	  return status === 429 || (typeof status === 'number' && status >= 500);
61	}
62	
63	// Unpriced models (e.g. a Venice fallback model) must not be costed at zero: that would let spend
64	// past the budget go uncounted. Price them as the most expensive known tier instead, so the meter
65	// fails closed rather than open.
66	const FALLBACK_COST_PER_MILLION = { input: 3, output: 15 };
67	
68	export function estimateCostUsd(model: string, inputTokens: number, outputTokens: number): number {
69	  const table = COST_PER_MILLION_TOKENS[model] ?? FALLBACK_COST_PER_MILLION;
70	  return (inputTokens / 1_000_000) * table.input + (outputTokens / 1_000_000) * table.output;
71	}
72	
73	function toOpenAiTool(tool: Tool) {
74	  return {
75	    type: 'function' as const,
76	    function: { name: tool.name, description: tool.description, parameters: z.toJSONSchema(tool.parameters) },
77	  };
78	}
79	
80	function toCompletion(raw: OpenAI.Chat.Completions.ChatCompletion, model: string, provider: string, costUsd: number, meter: CostMeter): Completion {
81	  const choice = raw.choices[0];
82	  const inputTokens = raw.usage?.prompt_tokens ?? 0;
83	  const outputTokens = raw.usage?.completion_tokens ?? 0;
84	  meter.add(costUsd);
85	  const toolCalls = choice?.message.tool_calls?.flatMap((tc): ToolCall[] =>
86	    tc.type === 'function' ? [{ id: tc.id, type: 'function', function: { name: tc.function.name, arguments: tc.function.arguments } }] : [],
87	  );
88	  const message: ChatMessage = {
89	    role: 'assistant',
90	    content: choice?.message.content ?? null,
91	    ...(toolCalls && toolCalls.length > 0 ? { tool_calls: toolCalls } : {}),
92	  };
93	  return { message, inputTokens, outputTokens, model, provider };
94	}
95	
96	export function createRouter(env: Env, meter: CostMeter): ModelClient {
97	  let lastCostHeader: number | null = null;
98	
99	  const costFetch = (async (input: Parameters<typeof fetch>[0], init?: Parameters<typeof fetch>[1]) => {
100	    const res = await fetch(input, init);
101	    const header = res.headers.get('x-litellm-response-cost');
102	    lastCostHeader = header ? Number(header) : null;
103	    return res;
104	  }) as typeof fetch;
105	
106	  const wrap = (client: OpenAI): OpenAI => (isTracingInitialized() ? wrapOpenAI(client) : client);
107	
108	  // maxRetries: 0 — our own loop below owns the 1s/2s/4s retry schedule; the SDK's default of 2
109	  // would otherwise retry silently underneath it, multiplying attempts and breaking that timing.
110	  const gatewayClient = wrap(
111	    new OpenAI({ baseURL: env.gatewayBaseUrl, apiKey: env.gatewayKey ?? 'unset', fetch: costFetch, maxRetries: 0 }),
112	  );
113	
114	  async function requestOnce(
115	    client: OpenAI,
116	    model: string,
117	    messages: ChatMessage[],
118	    tools: Tool[] | undefined,
119	    maxTokens: number | undefined,
120	  ): Promise<{ raw: OpenAI.Chat.Completions.ChatCompletion; costUsd: number }> {
121	    lastCostHeader = null;
122	    const raw = await client.chat.completions.create({
123	      model,
124	      messages: messages as OpenAI.Chat.Completions.ChatCompletionMessageParam[],
125	      tools: tools && tools.length > 0 ? tools.map(toOpenAiTool) : undefined,
126	      max_tokens: maxTokens,
127	    });
128	    const inputTokens = raw.usage?.prompt_tokens ?? 0;
129	    const outputTokens = raw.usage?.completion_tokens ?? 0;
130	    const costUsd = lastCostHeader ?? estimateCostUsd(model, inputTokens, outputTokens);
131	    return { raw, costUsd };
132	  }
133	
134	  async function complete(req: { role: Role; messages: ChatMessage[]; tools?: Tool[]; maxTokens?: number }): Promise<Completion> {
135	    meter.assertWithin();
136	    await sharedLimiter.acquire();
137	    const model = MODEL_BY_ROLE[req.role];
138	
139	    let lastErr: unknown;
140	    let retriesExhausted = false;
141	    for (let attempt = 0; attempt <= RETRY_WAITS_MS.length; attempt++) {
142	      try {
143	        const { raw, costUsd } = await requestOnce(gatewayClient, model, req.messages, req.tools, req.maxTokens);
144	        return toCompletion(raw, model, 'gateway', costUsd, meter);
145	      } catch (err) {
146	        const status = (err as { status?: unknown } | null)?.status;
147	        if (!isRetryableStatus(status)) throw err; // not a 429/5xx: fail fast, never contact Venice with it
148	        lastErr = err;
149	        if (attempt === RETRY_WAITS_MS.length) {
150	          retriesExhausted = true;
151	          break;
152	        }
153	        await sleep(RETRY_WAITS_MS[attempt]!);
154	      }
155	    }
156	
157	    // Only reachable once the 429/5xx retry schedule above is exhausted — "if they fail" in the spec
158	    // refers to those retries, not to a non-retryable error, which already threw above.
159	    if (retriesExhausted) {
160	      const veniceModel = process.env[`VENICE_MODEL_${req.role.toUpperCase()}`];
161	      if (env.veniceKey && veniceModel) {
162	        const veniceClient = wrap(
163	          new OpenAI({ baseURL: 'https://api.venice.ai/api/v1', apiKey: env.veniceKey, fetch: costFetch, maxRetries: 0 }),
164	        );
165	        const { raw, costUsd } = await requestOnce(veniceClient, veniceModel, req.messages, req.tools, req.maxTokens);
166	        return toCompletion(raw, veniceModel, 'venice', costUsd, meter);
167	      }
168	    }
169	    throw lastErr;
170	  }
171	
172	  return { complete };
173	}
174

